  "subtype": "focus_inference",
  "implied_focus": "The aspects/dimensions of a purchase that Amazon reviewers discuss (an aspect taxonomy of review content)",
  "per_column": [
    {
      "name": "product_category",
      "supports_focus": true,
      "rationale": "Establishes the product type context that conditions which purchase aspects reviewers can talk about; a coherent facet of the aspect-taxonomy focus, though slightly more of a segmentation attribute than an aspect itself."
    },
    {
      "name": "functional_performance_issue",
      "supports_focus": true,
      "rationale": "Directly captures a major aspect reviewers discuss for physical/functional products (does it work, performs vs expectations); a clear aspect facet at useful granularity."
    },
    {
      "name": "content_creative_quality",
      "supports_focus": true,
      "rationale": "Captures the aspect reviewers discuss for media products (plot, writing, musical quality, etc.); a complementary aspect facet covering the media portion of the catalogue."
    }
  ],
  "focus_coherence": 0.85,
